
import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
const s=fs.readFileSync('supabase/functions/hub/index.ts','utf8');
function extract(name){const at=s.indexOf('async function '+name+'(');assert(at>=0);const end=s.indexOf('\n}',at)+2;return s.slice(at,end)}
let receivedOr=[],rows=[{id:'gmail:1',provider:'gmail',provider_labels:['INBOX'],mailbox_owner:'a@example.com'},{id:'zoho:2',provider:'zoho',hub_folder:'inbox',mailbox_owner:'b@example.com'},{id:'zoho:3',provider:'zoho',hub_folder:'trash',mailbox_owner:'b@example.com'},{id:'zoho:4',provider:'zoho',hub_folder:'archive',mailbox_owner:'b@example.com'},{id:'zoho:5',provider:'zoho',hub_folder:'spam',mailbox_owner:'b@example.com'}];
function query(){const q={select(){return q},order(){return q},range(){return q},eq(){return q},in(){return q},contains(){return q},or(value){receivedOr.push(value);return q},then(resolve){const inbox=receivedOr.at(-1);const data=rows.filter(x=>x.provider==='gmail'?x.provider_labels.includes('INBOX'):!x.hub_folder||x.hub_folder==='inbox');assert(inbox.includes('hub_folder.eq.inbox')&&inbox.includes('hub_folder.is.null')&&!inbox.includes('provider.neq.gmail'));resolve({data,count:data.length})}};return q}
